import type { GitHubAdapter, GitHubPR } from './adapter.js'
import type { HackonConfig } from '../config/schema.js'
import type { TaskRecord } from '../registry/types.js'
import { getWorktreeDiffStats } from '../gates/diff-check.js'

export interface PRBodyParams {
  task: TaskRecord
  summary: string
  worktreePath: string
  baseBranch: string
  gateResults?: string[]
}

export function buildPRBody(params: PRBodyParams): string {
  const { task, summary, worktreePath, baseBranch, gateResults } = params

  const sourceLabel = task.source.type === 'github_issue'
    ? `GitHub issue #${task.source.id}`
    : task.source.type === 'integration_gap'
      ? `Integration test gap: ${task.source.id}`
      : `Repository signal: ${task.source.id}`

  const diffStats = getWorktreeDiffStats(worktreePath, baseBranch)
  const fileList = diffStats.files.map((f) => `- ${f}`).join('\n')

  const validationSection = gateResults && gateResults.length > 0
    ? gateResults.map((g) => `- ${g}`).join('\n')
    : '- (pending)'

  return `Source: ${sourceLabel}

## Summary
${summary}

## Changes
${fileList}
- Diff: +${diffStats.additions} / -${diffStats.deletions} (${diffStats.totalLines} total lines)

## Validation
${validationSection}

## Expected Contribution Classes
${task.expectedClasses.map((c) => `- ${c}`).join('\n')}
`
}

export async function createDraftPR(
  github: GitHubAdapter,
  config: HackonConfig,
  task: TaskRecord,
  body: string,
): Promise<GitHubPR> {
  const head = `${config.github.forkOwner}:${task.branchName}`

  return github.createPullRequest({
    owner: config.github.upstreamOwner,
    repo: config.github.upstreamRepo,
    title: task.source.title,
    body,
    head,
    base: config.github.baseBranch,
    draft: true,
  })
}

export async function markPRReady(
  github: GitHubAdapter,
  config: HackonConfig,
  prNumber: number,
): Promise<GitHubPR> {
  return github.updatePullRequest({
    owner: config.github.upstreamOwner,
    repo: config.github.upstreamRepo,
    number: prNumber,
    draft: false,
  })
}
